 return -1;
 }

 // Técnica 2: Mede tempo de execução (simplificada)
 auto start = std::chrono::high_resolution_clock::now();

 // ... aqui o código real de descompressão ...

 auto end = std::chrono::high_resolution_clock::now();
 auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
 if (duration.count() < 5) {
 return -1; // Tempo anormalmente curto
 }

 return 0;
}
```

---

### Considerações finais
- **Anti-debug não é à prova de balas.** Ferramentas como OllyDbg, x64dbg e IDA Pro têm modos de depuração que podem ignorar essas verificações. Para proteção séria, combine com ofuscação de código, criptografia de funções e empacotamento.
- **Teste em ambientes controlados.** Use um depurador local para verificar se a proteção funciona, mas lembre-se de que o atacante terá mais recursos.
- **Não se esqueça de incluir os cabeçalhos necessários** (`#include <windows.h>` e `#include <chrono>` se usar C++11).

